//! Generates `src/ast/generated.rs` from `grammar/gsc.ungram` and checks that the grammar and
//! `SyntaxKind` agree. When the generated file is stale the test rewrites it and fails; run the
//! tests again to see them pass.

use std::collections::BTreeSet;
use std::fmt::Write;
use std::path::{Path, PathBuf};

use gsc_syntax::SyntaxKind;
use ungrammar::{Grammar, Rule};

/// Nodes whose node accessors are hand-written in `src/ast/ext.rs` (positional reading of the
/// grammar would be wrong for them). Their token accessors are still generated.
const MANUAL: &[&str] = &[
    "CallExpr",
    "PointerCallExpr",
    "MethodCallExpr",
    "FieldExpr",
    "AnimRef",
    "CastExpr",
    "GotoStmt",
];

fn crate_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn grammar() -> Grammar {
    let path = crate_dir().join("../../grammar/gsc.ungram");
    let text = std::fs::read_to_string(&path).expect("read gsc.ungram");
    text.parse().expect("gsc.ungram parses")
}

fn screaming(name: &str) -> String {
    let mut out = String::new();
    for (i, c) in name.chars().enumerate() {
        if c.is_ascii_uppercase() && i > 0 {
            out.push('_');
        }
        out.push(c.to_ascii_uppercase());
    }
    out
}

fn snake(name: &str) -> String {
    screaming(name).to_ascii_lowercase()
}

fn kind_named(name: &str) -> Option<SyntaxKind> {
    SyntaxKind::all().iter().copied().find(|k| k.name() == name)
}

#[derive(Debug)]
struct NodeField {
    ty: String,
    label: Option<String>,
    many: bool,
}

fn walk(
    g: &Grammar,
    rule: &Rule,
    label: Option<&str>,
    many: bool,
    nodes: &mut Vec<NodeField>,
    tokens: &mut Vec<String>,
) {
    match rule {
        Rule::Labeled { label, rule } => walk(g, rule, Some(label), many, nodes, tokens),
        Rule::Node(n) => nodes.push(NodeField {
            ty: g[*n].name.clone(),
            label: label.map(str::to_owned),
            many,
        }),
        Rule::Token(t) => {
            let name = g[*t].name.clone();
            if !tokens.contains(&name) {
                tokens.push(name);
            }
        }
        Rule::Seq(rules) | Rule::Alt(rules) => {
            for r in rules {
                walk(g, r, label, many, nodes, tokens);
            }
        }
        Rule::Opt(r) => walk(g, r, label, many, nodes, tokens),
        Rule::Rep(r) => walk(g, r, label, true, nodes, tokens),
    }
}

fn is_enum(g: &Grammar, rule: &Rule) -> Option<Vec<String>> {
    match rule {
        Rule::Alt(alts) => alts
            .iter()
            .map(|a| match a {
                Rule::Node(n) => Some(g[*n].name.clone()),
                _ => None,
            })
            .collect(),
        _ => None,
    }
}

fn token_method(spelling: &str) -> String {
    let kind = SyntaxKind::from_grammar_token(spelling)
        .unwrap_or_else(|| panic!("gsc.ungram token '{spelling}' has no SyntaxKind"));
    format!("{}_token", kind.name().to_ascii_lowercase())
}

fn plural(name: &str) -> String {
    if name.ends_with('s') {
        format!("{name}es")
    } else {
        format!("{name}s")
    }
}

fn generate(g: &Grammar) -> String {
    let mut enums = Vec::new();
    let mut structs = Vec::new();
    for n in g.iter() {
        let data = &g[n];
        match is_enum(g, &data.rule) {
            Some(variants) => enums.push((data.name.clone(), variants)),
            None => structs.push(n),
        }
    }
    let enum_names: BTreeSet<String> = enums.iter().map(|(n, _)| n.clone()).collect();

    let mut out = String::new();
    out.push_str(
        "//! Generated by `cargo test -p gsc_syntax --test sourcegen` from grammar/gsc.ungram.\n\
         //! Do not edit by hand.\n\n\
         #![allow(clippy::all)]\n\n\
         use crate::ast::{support, AstChildren, AstNode};\n\
         use crate::{SyntaxKind, SyntaxKind::*, SyntaxNode, SyntaxToken};\n\n",
    );

    for n in &structs {
        let data = &g[*n];
        let name = &data.name;
        let kind = screaming(name);
        assert!(
            kind_named(&kind).is_some(),
            "node {name}: no SyntaxKind::{kind}"
        );
        let mut nodes = Vec::new();
        let mut tokens = Vec::new();
        walk(g, &data.rule, None, false, &mut nodes, &mut tokens);

        let _ = writeln!(out, "#[derive(Debug, Clone, PartialEq, Eq, Hash)]");
        let _ = writeln!(
            out,
            "pub struct {name} {{\n    pub(crate) syntax: SyntaxNode,\n}}\n"
        );
        let _ = writeln!(out, "impl {name} {{");
        let manual = MANUAL.contains(&name.as_str());
        if !manual {
            let mut done: BTreeSet<String> = BTreeSet::new();
            for f in &nodes {
                let same: Vec<&NodeField> = nodes.iter().filter(|x| x.ty == f.ty).collect();
                let unlabeled = same.iter().filter(|x| x.label.is_none()).count();
                let many = f.label.is_none() && (f.many || unlabeled > 1);
                let method = match &f.label {
                    Some(l) => l.clone(),
                    None if many => plural(&snake(&f.ty)),
                    None => snake(&f.ty),
                };
                if !done.insert(method.clone()) {
                    continue;
                }
                let ty = &f.ty;
                if many {
                    let _ = writeln!(
                        out,
                        "    pub fn {method}(&self) -> AstChildren<{ty}> {{\n        support::children(&self.syntax)\n    }}"
                    );
                } else {
                    let nth = same.iter().position(|x| std::ptr::eq(*x, f)).unwrap();
                    let _ = writeln!(
                        out,
                        "    pub fn {method}(&self) -> Option<{ty}> {{\n        support::child(&self.syntax, {nth})\n    }}"
                    );
                }
            }
        }
        for t in &tokens {
            let method = token_method(t);
            let kind = SyntaxKind::from_grammar_token(t).unwrap().name();
            let _ = writeln!(
                out,
                "    pub fn {method}(&self) -> Option<SyntaxToken> {{\n        support::token(&self.syntax, {kind})\n    }}"
            );
        }
        let _ = writeln!(out, "}}\n");
        let _ = writeln!(
            out,
            "impl AstNode for {name} {{\n    fn can_cast(kind: SyntaxKind) -> bool {{\n        kind == {kind}\n    }}\n    fn cast(syntax: SyntaxNode) -> Option<Self> {{\n        Self::can_cast(syntax.kind()).then_some({name} {{ syntax }})\n    }}\n    fn syntax(&self) -> &SyntaxNode {{\n        &self.syntax\n    }}\n}}\n"
        );
    }

    for (name, variants) in &enums {
        for v in variants {
            assert!(
                !enum_names.contains(v),
                "enum {name}: variant {v} is an enum"
            );
        }
        let _ = writeln!(out, "#[derive(Debug, Clone, PartialEq, Eq, Hash)]");
        let _ = writeln!(out, "pub enum {name} {{");
        for v in variants {
            let _ = writeln!(out, "    {v}({v}),");
        }
        let _ = writeln!(out, "}}\n");
        let kinds: Vec<String> = variants.iter().map(|v| screaming(v)).collect();
        let _ = writeln!(out, "impl AstNode for {name} {{");
        let _ = writeln!(
            out,
            "    fn can_cast(kind: SyntaxKind) -> bool {{\n        matches!(kind, {})\n    }}",
            kinds.join(" | ")
        );
        let _ = writeln!(out, "    fn cast(syntax: SyntaxNode) -> Option<Self> {{\n        let res = match syntax.kind() {{");
        for (v, k) in variants.iter().zip(&kinds) {
            let _ = writeln!(out, "            {k} => {name}::{v}({v} {{ syntax }}),");
        }
        let _ = writeln!(
            out,
            "            _ => return None,\n        }};\n        Some(res)\n    }}"
        );
        let _ = writeln!(
            out,
            "    fn syntax(&self) -> &SyntaxNode {{\n        match self {{"
        );
        for v in variants {
            let _ = writeln!(out, "            {name}::{v}(it) => &it.syntax,");
        }
        let _ = writeln!(out, "        }}\n    }}\n}}\n");
        for v in variants {
            let _ = writeln!(
                out,
                "impl From<{v}> for {name} {{\n    fn from(node: {v}) -> {name} {{\n        {name}::{v}(node)\n    }}\n}}\n"
            );
        }
    }
    out
}

fn rustfmt(code: &str) -> String {
    use std::io::Write as _;
    use std::process::{Command, Stdio};
    let mut child = Command::new("rustfmt")
        .args([
            "--edition",
            "2021",
            "--emit",
            "stdout",
            "--config",
            "max_width=100",
        ])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("rustfmt is installed");
    child
        .stdin
        .take()
        .unwrap()
        .write_all(code.as_bytes())
        .unwrap();
    let out = child.wait_with_output().unwrap();
    assert!(out.status.success(), "rustfmt failed on the generated code");
    String::from_utf8(out.stdout).unwrap().replace("\r\n", "\n")
}

fn ensure_file(path: &Path, contents: &str) {
    let old = std::fs::read_to_string(path)
        .unwrap_or_default()
        .replace("\r\n", "\n");
    if old == contents {
        return;
    }
    std::fs::write(path, contents).unwrap();
    panic!(
        "{} was stale and has been regenerated; run the tests again",
        path.display()
    );
}

#[test]
fn generated_ast_is_fresh() {
    let g = grammar();
    let code = rustfmt(&generate(&g));
    ensure_file(&crate_dir().join("src/ast/generated.rs"), &code);
}

#[test]
fn every_node_kind_has_a_rule() {
    let g = grammar();
    let rules: BTreeSet<String> = g.iter().map(|n| screaming(&g[n].name)).collect();
    for k in SyntaxKind::all() {
        if k.is_node() && *k != SyntaxKind::ERROR {
            assert!(
                rules.contains(k.name()),
                "SyntaxKind::{} has no rule in gsc.ungram",
                k.name()
            );
        }
    }
}
